#![cfg(not(target_arch = "wasm32"))]
#[test]
#[ignore = "requires YOUCRAFT_TRACK_FIXTURE, generated by FFmpeg as an external oracle"]
fn reads_two_audio_and_subtitle_tracks_independently() {
    let path = std::env::var("YOUCRAFT_TRACK_FIXTURE").unwrap();
    let bytes = std::fs::read(&path).unwrap();
    let source = filmcraft_media::open_bytes("tracks.mkv", bytes.into(), &filmcraft_codecs::openers()).unwrap();
    assert_eq!(source.audio_track_labels().len(), 2);
    assert!(source.audio_track_labels()[1].starts_with("fra"));
    assert_eq!(source.subtitle_tracks().len(), 2);
    let english = source.subtitle_cues(0).unwrap();
    let french = source.subtitle_cues(1).unwrap();
    assert_eq!(english.len(), 2);
    assert_eq!(english[0].text, "Hello YouCraft");
    assert_eq!(french[0].text, "Bonjour YouCraft");
    assert!((english[0].end - english[0].start).seconds() - 2.0 < 0.001);
    assert!(source.subtitle_cues(usize::MAX).is_err());
    let a = source.audio_stream(0, 24000, 1024, 48000).unwrap();
    let b = source.audio_stream(1, 24000, 1024, 48000).unwrap();
    assert_ne!(a.channels, b.channels);
}
